package com.jinloes.practice;
import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: a lowercase string, for example: aab"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) {runInput(String.join(" ",args).trim());return;} assertValidReorganization("aab",Solution.reorganize("aab")); assertThat(Solution.reorganize("aaab")).as("Example 2").isEmpty(); System.out.println("Examples passed: 2"); } private static void runInput(String input) { if(!input.matches("[a-z]*")){System.out.println("Could not read \""+input+"\". "+USAGE);return;} System.out.println(Solution.reorganize(input)); } private static void assertValidReorganization(String input,String output){assertThat(output).hasSize(input.length());assertThat(sorted(output)).isEqualTo(sorted(input));for(int i=1;i<output.length();i++)assertThat(output.charAt(i)).as("adjacent characters at "+i).isNotEqualTo(output.charAt(i-1));} private static String sorted(String text){return text.chars().sorted().collect(StringBuilder::new,StringBuilder::appendCodePoint,StringBuilder::append).toString();} }

